#!/usr/bin/env python3
"""Galaxy Watch 8 ONLY: supply the raw GKI ABI list normally generated by Kleaf.

Read the input source's GKI target and local filegroups without executing its
BUILD file. Keep MODULE_SIG_PROTECT and TRIM_UNUSED_KSYMS unchanged. GW7 does
not use this helper.
"""
from __future__ import annotations

import ast
import configparser
import re
from pathlib import Path

from common import sha256, write_json
from prepare_kernel import read_config


class BuildDefinition:
    """Resolve only literal KMI attributes, constants, filegroups and glob()."""

    def __init__(self, source: Path):
        self.source = source.resolve()
        self.path = self.source / 'BUILD.bazel'
        tree = ast.parse(self.path.read_text(encoding='utf-8'), filename=str(self.path))
        self.constants = {target.id: statement.value for statement in tree.body
                          if isinstance(statement, ast.Assign) for target in statement.targets
                          if isinstance(target, ast.Name)}
        self.calls = [statement.value for statement in tree.body
                      if isinstance(statement, ast.Expr) and isinstance(statement.value, ast.Call)
                      and isinstance(statement.value.func, ast.Name)]
        self.groups = {self.value(self.keyword(call, 'name')): self.keyword(call, 'srcs')
                       for call in self.calls if call.func.id == 'filegroup'}

    @staticmethod
    def keyword(call: ast.Call, name: str):
        return next((item.value for item in call.keywords if item.arg == name), ast.Constant(None))

    def resolve(self, node, seen=()):
        if isinstance(node, ast.Name) and node.id in self.constants:
            if node.id in seen:
                raise ValueError(f'Cyclic GW8 BUILD constant: {node.id}')
            return self.resolve(self.constants[node.id], (*seen, node.id))
        return node

    def mapping(self, node) -> dict:
        node = self.resolve(node)
        if not isinstance(node, ast.Dict) or any(key is None for key in node.keys):
            raise ValueError('GW8 ABI target must use an explicit BUILD dictionary')
        return {self.value(key): value for key, value in zip(node.keys, node.values)}

    def value(self, node):
        node = self.resolve(node)
        if isinstance(node, ast.Constant):
            return node.value
        if isinstance(node, (ast.List, ast.Tuple)):
            return [self.value(item) for item in node.elts]
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
            left, right = self.value(node.left), self.value(node.right)
            if type(left) is type(right) and isinstance(left, (str, list)):
                return left + right
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'glob':
            include = self.value(node.args[0] if node.args else self.keyword(node, 'include'))
            exclude = self.value(self.keyword(node, 'exclude')) or []
            if not isinstance(include, list) or not isinstance(exclude, list):
                raise ValueError('GW8 ABI glob must contain explicit pattern lists')
            matches = []
            for patterns in (include, exclude):
                files = set()
                for pattern in patterns:
                    self.local_path(pattern)
                    files.update(path.relative_to(self.source).as_posix()
                                 for path in self.source.glob(pattern) if path.is_file())
                matches.append(files)
            result = sorted(matches[0] - matches[1])
            if not result and self.value(self.keyword(node, 'allow_empty')) is False:
                raise ValueError('GW8 ABI glob matched no files')
            return result
        raise ValueError(f'Unsupported GW8 ABI BUILD expression at line {getattr(node, "lineno", "?")}; '
                         'adapt the ABI resolver to this source definition')

    def local_path(self, name: str) -> Path:
        if not isinstance(name, str) or not name or '\\' in name or ':' in name:
            raise ValueError(f'Invalid GW8 ABI source path: {name!r}')
        path = (self.source / name).resolve()
        if not path.is_relative_to(self.source):
            raise ValueError(f'GW8 ABI source path escapes the kernel tree: {name}')
        return path

    def files(self, label: str, seen=()) -> list[Path]:
        if label.startswith('//'):
            package, separator, label = label[2:].partition(':')
            if not separator or package not in ('common', self.source.name):
                raise ValueError(f'Unsupported GW8 ABI package: //{package}')
        label = label.removeprefix(':')
        if label in self.groups:
            if label in seen:
                raise ValueError(f'Cyclic GW8 ABI filegroup: {label}')
            return [path for child in self.value(self.groups[label])
                    for path in self.files(child, (*seen, label))]
        return [self.local_path(label)]

    def symbol_lists(self, config: dict) -> tuple[str, list[Path]]:
        targets = {}
        for call in self.calls:
            if call.func.id == 'define_common_kernels':
                targets.update({name: self.mapping(node) for name, node in
                                self.mapping(self.keyword(call, 'target_configs')).items()
                                if name.startswith('kernel_aarch64')})
            elif call.func.id == 'kernel_build':
                name = self.value(self.keyword(call, 'name'))
                if name and name.startswith('kernel_aarch64'):
                    targets[name] = {item.arg: item.value for item in call.keywords}
        target = 'kernel_aarch64'
        for size in ('16', '64'):
            candidate = f'kernel_aarch64_{size}k'
            if config.get(f'CONFIG_ARM64_{size}K_PAGES') == 'y' and candidate in targets:
                target = candidate
        if target not in targets:
            raise ValueError(f'Cannot find GW8 {target} ABI definition in {self.path}')
        fields = targets[target]
        main = self.value(fields.get('kmi_symbol_list', ast.Constant(None)))
        additional = self.value(fields.get('additional_kmi_symbol_lists', ast.List(elts=[]))) or []
        if not isinstance(main, str) or not main or not isinstance(additional, list):
            raise ValueError(f'GW8 {target} must define its KMI symbol lists explicitly')
        paths = [path for label in [main, *additional] for path in self.files(label)]
        return target, list(dict.fromkeys(paths))


def prepare_abi_symbols(source: Path, output: Path, report_path: Path) -> dict:
    config = read_config(output / '.config')
    name = ast.literal_eval(config.get('CONFIG_UNUSED_KSYMS_WHITELIST', '""'))
    report = {'device_family': 'galaxy-watch8', 'generated': False,
              'module_sig_protect': config.get('CONFIG_MODULE_SIG_PROTECT', 'n'),
              'trim_unused_ksyms': config.get('CONFIG_TRIM_UNUSED_KSYMS', 'n')}
    if not name:
        report['reason'] = 'The input kernel config does not request a KMI whitelist file'
        write_json(report_path, report)
        return report
    output = output.resolve()
    raw = (output / name).resolve()
    if Path(name).is_absolute() or not raw.is_relative_to(output):
        raise ValueError('GW8 generated ABI whitelist must be inside the output directory')
    definition = BuildDefinition(source)
    target, paths = definition.symbol_lists(config)
    # Match Kleaf flatten_symbol_list: preserve case, combine matching INI
    # sections, sort and deduplicate. Never modify the original source lists.
    parser = configparser.ConfigParser(allow_no_value=True, strict=False, interpolation=None)
    parser.optionxform = str
    inputs = []
    for path in paths:
        if not path.is_file():
            raise ValueError(f'GW8 ABI symbol list is missing: {path}')
        parser.read_string(path.read_text(encoding='utf-8'), source=str(path))
        inputs.append({'path': path.relative_to(definition.source).as_posix(), 'sha256': sha256(path)})
    symbols = {symbol for section in parser.sections() if section.endswith(('whitelist', 'symbol_list'))
               for symbol in parser[section]}
    if not symbols or any(not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', symbol) for symbol in symbols):
        raise ValueError('GW8 ABI inputs contain no symbols or contain invalid symbol names')
    raw.parent.mkdir(parents=True, exist_ok=True)
    raw.write_text(''.join(symbol + '\n' for symbol in sorted(symbols)), encoding='utf-8', newline='\n')
    report.update({'generated': True, 'target': target, 'build_file_sha256': sha256(definition.path),
                   'inputs': inputs, 'output': raw.relative_to(output).as_posix(),
                   'symbol_count': len(symbols), 'sha256': sha256(raw)})
    write_json(report_path, report)
    print(f'GW8 ABI: generated {report["output"]} from {len(inputs)} source lists '
          f'({len(symbols)} symbols; {target})', flush=True)
    return report
